guardrail.bad:
try {
    suspendingCall()
} catch (e: Exception) {
    logger.error("Failed", e)  // swallows CancellationException — coroutine never cancels
}

guardrail.good:
try {
    suspendingCall()
} catch (e: CancellationException) {
    throw e  // always rethrow
} catch (e: Exception) {
    logger.error("Failed", e)
}

guardrail.bad:
suspend fun readFile(path: String): String {
    return File(path).readText()  // blocks the coroutine dispatcher thread
}

guardrail.good:
suspend fun readFile(path: String): String = withContext(Dispatchers.IO) {
    File(path).readText()
}

val result = withTimeoutOrNull(5_000L) {
    externalApi.fetchUser(id)
} ?: throw ServiceUnavailableException("User service timed out after 5s")

pattern.example:
data class User(
    val id: UserId,
    val email: Email,
    val name: String,
    val role: Role = Role.VIEWER,
) {
    init {
        require(name.isNotBlank()) { "User name must not be blank" }
    }
}

// Value class: zero runtime overhead, prevents passing wrong string in wrong position
@JvmInline
value class UserId(val value: String) {
    init { require(value.isNotBlank()) { "UserId must not be blank" } }
}

sealed interface Result<out T> {
    data class Success<T>(val data: T) : Result<T>
    data class Failure(val error: AppError) : Result<Nothing>
}

sealed class AppError(val message: String) {
    data class NotFound(val resource: String, val id: String) :
        AppError("$resource with ID $id not found")
    data class Validation(val field: String, val reason: String) :
        AppError("Validation failed for $field: $reason")
    data class Unauthorized(val detail: String = "Authentication required") :
        AppError(detail)
}

fun <T> Result<T>.getOrThrow(): T = when (this) {
    is Result.Success -> data
    is Result.Failure -> throw error.toException()
}

// apply: configure builder-style and return the object
val request = HttpRequest.Builder().apply {
    url(endpoint)
    header("Authorization", "Bearer $token")
    timeout(Duration.ofSeconds(30))
}.build()

// also: non-mutating side effect (logging, events) — chain continues with original value
val savedUser = userRepository.save(newUser).also { user ->
    logger.info("Created user: ${user.id}")
}

// let: nullable transform or scoped variable
val displayName = user?.name?.let { name ->
    if (name.length > 20) name.take(17) + "..." else name
} ?: "Anonymous"

// Parallel fetch — both run concurrently, both must succeed
suspend fun getUserWithOrders(id: UserId): UserWithOrders = coroutineScope {
    val user = async { userService.getUser(id) }
    val orders = async { orderService.getOrders(id) }
    UserWithOrders(user.await(), orders.await())
}

// supervisorScope — one child failure does not cancel others
suspend fun fetchDashboard(id: UserId): Dashboard = supervisorScope {
    val user = async { userService.getUser(id) }
    val notifications = async {
        runCatching { notificationService.get(id) }.getOrDefault(emptyList())
    }
    Dashboard(user.await(), notifications.await())
}

testing.pattern:
class UserServiceTest {
    private val userRepository = mockk<UserRepository>()
    private val eventBus = mockk<EventBus>(relaxed = true)
    private val service = UserService(userRepository, eventBus)

    @Nested
    @DisplayName("createUser")
    inner class CreateUser {
        @Test
        fun `creates user with valid input`() = runTest {
            coEvery { userRepository.save(any()) } returns mockUser
            val result = service.createUser(validInput)

            assertThat(result).isInstanceOf(Result.Success::class.java)
            coVerify { userRepository.save(any()) }
            coVerify { eventBus.publish(any<UserCreatedEvent>()) }
        }

        @Test
        fun `fails with blank name`() = runTest {
            val result = service.createUser(blankNameInput)

            assertThat(result).isInstanceOf(Result.Failure::class.java)
            coVerify(exactly = 0) { userRepository.save(any()) }
        }
    }
}

companion object {
    @JvmStatic
    fun emailCases() = listOf(
        Arguments.of("user@example.com", true),
        Arguments.of("invalid-email", false),
        Arguments.of("", false),
    )
}

@ParameterizedTest(name = "email \"{0}\" valid={1}")
@MethodSource("emailCases")
fun `validates email format`(email: String, expected: Boolean) {
    val result = runCatching { Email(email) }
    assertThat(result.isSuccess).isEqualTo(expected)
}

